fn less_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Create a new vector to hold the results
    let mut result = Vec::with_capacity(a.len());

    // Iterate through both vectors simultaneously
    for (x, y) in a.iter().zip(b.iter()) {
        // Compare the elements and push the result to the result vector
        result.push(x <= y);
    }

    // Return the result vector
    result
}